package com.example.suinsrt;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;

/**
 * Entry point for the SUINSRT Spring Boot application.
 *
 * <p>Migrated from the COBOL program SUINSRT (CICS + COBOL + DB2).
 * The program reads a JSON file containing up to 30 employee records,
 * transforms the data, encrypts each password via an external service
 * (formerly CALL 'CRYPTPGM'), and persists the employees to PostgreSQL.
 */
@SpringBootApplication
public class Application {

    public static void main(String[] args) {
        SpringApplication.run(Application.class, args);
    }
}

