package com.example.suinsrt.model;

import jakarta.persistence.*;
import java.math.BigDecimal;

/**
 * JPA entity that maps to the EMPLOYEE table.
 *
 * <p>Field mapping from COBOL WS-EMPLIST table:
 * <ul>
 *   <li>EMPID       PIC 9(8)        → long empId</li>
 *   <li>PASSW       PIC X(8)        → String password</li>
 *   <li>FIRSTNAME   PIC X(30)       → String firstName</li>
 *   <li>LASTNAME    PIC X(30)       → String lastName</li>
 *   <li>ADDRE       PIC X(100)      → String address</li>
 *   <li>CITY        PIC X(50)       → String city</li>
 *   <li>ZIPCODE     PIC X(15)       → String zipCode</li>
 *   <li>TELEPHONE   PIC X(10)       → String telephone</li>
 *   <li>EMAIL       PIC X(100)      → String email</li>
 *   <li>ADMINDATE   PIC X(10)       → String adminDate</li>
 *   <li>SALARY      PIC 9(6)V9(2)   → BigDecimal salary</li>
 *   <li>DEPTID      PIC 9(9)        → long deptId</li>
 * </ul>
 */
@Entity
@Table(name = "employee")
public class Employee {

    /** Primary key – derived from raw EMPID + 10 000 000 offset (COBOL logic). */
    @Id
    @Column(name = "emp_id", nullable = false)
    private long empId;

    /** Encrypted password stored after CALL 'CRYPTPGM'. */
    @Column(name = "password", length = 8)
    private String password;

    @Column(name = "first_name", length = 30)
    private String firstName;

    @Column(name = "last_name", length = 30)
    private String lastName;

    @Column(name = "address", length = 100)
    private String address;

    @Column(name = "city", length = 50)
    private String city;

    @Column(name = "zip_code", length = 15)
    private String zipCode;

    @Column(name = "telephone", length = 10)
    private String telephone;

    @Column(name = "email", length = 100)
    private String email;

    /**
     * Administration date stored in MM/DD/YYYY format after the COBOL
     * date-rearrangement logic in paragraph 0210-MOVE-TABLE.
     */
    @Column(name = "admin_date", length = 10)
    private String adminDate;

    /** COMP-3 packed decimal → BigDecimal with 2 decimal places. */
    @Column(name = "salary", precision = 8, scale = 2)
    private BigDecimal salary;

    @Column(name = "dept_id")
    private long deptId;

    // ----------------------------------------------------------------
    // Constructors
    // ----------------------------------------------------------------

    public Employee() {}

    public Employee(long empId, String password, String firstName, String lastName,
                    String address, String city, String zipCode, String telephone,
                    String email, String adminDate, BigDecimal salary, long deptId) {
        this.empId     = empId;
        this.password  = password;
        this.firstName = firstName;
        this.lastName  = lastName;
        this.address   = address;
        this.city      = city;
        this.zipCode   = zipCode;
        this.telephone = telephone;
        this.email     = email;
        this.adminDate = adminDate;
        this.salary    = salary;
        this.deptId    = deptId;
    }

    // ----------------------------------------------------------------
    // Getters & Setters
    // ----------------------------------------------------------------

    public long getEmpId()                  { return empId; }
    public void setEmpId(long empId)        { this.empId = empId; }

    public String getPassword()             { return password; }
    public void setPassword(String p)       { this.password = p; }

    public String getFirstName()            { return firstName; }
    public void setFirstName(String v)      { this.firstName = v; }

    public String getLastName()             { return lastName; }
    public void setLastName(String v)       { this.lastName = v; }

    public String getAddress()              { return address; }
    public void setAddress(String v)        { this.address = v; }

    public String getCity()                 { return city; }
    public void setCity(String v)           { this.city = v; }

    public String getZipCode()              { return zipCode; }
    public void setZipCode(String v)        { this.zipCode = v; }

    public String getTelephone()            { return telephone; }
    public void setTelephone(String v)      { this.telephone = v; }

    public String getEmail()                { return email; }
    public void setEmail(String v)          { this.email = v; }

    public String getAdminDate()            { return adminDate; }
    public void setAdminDate(String v)      { this.adminDate = v; }

    public BigDecimal getSalary()           { return salary; }
    public void setSalary(BigDecimal v)     { this.salary = v; }

    public long getDeptId()                 { return deptId; }
    public void setDeptId(long v)           { this.deptId = v; }
}

