package com.example.suinsrt.dto;

import com.fasterxml.jackson.annotation.JsonProperty;
import java.math.BigDecimal;

/**
 * DTO that mirrors one entry in the WS-EMPLIST OCCURS 30 table.
 *
 * <p>Jackson deserialises the raw JSON file (formerly read by the COBOL
 * {@code JSON PARSE IN-JSON INTO WS-EMPLIST} statement) into a list of
 * these records.
 *
 * <p>Field names match the lowercase JSON keys expected from the COBOL
 * JSON PARSE source (COBOL field names lowercased).
 */
public record EmployeeInputRecord(

        /** EMPID PIC 9(8) – raw value before the +10 000 000 offset is applied. */
        @JsonProperty("empid")     long empId,

        /** PASSW PIC X(8). */
        @JsonProperty("passw")     String password,

        /** FIRSTNAME PIC X(30). */
        @JsonProperty("firstname") String firstName,

        /** LASTNAME PIC X(30). */
        @JsonProperty("lastname")  String lastName,

        /** ADDRE PIC X(100). */
        @JsonProperty("addre")     String address,

        /** CITY PIC X(50). */
        @JsonProperty("city")      String city,

        /** ZIPCODE PIC X(15). */
        @JsonProperty("zipcode")   String zipCode,

        /** TELEPHONE PIC X(10). */
        @JsonProperty("telephone") String telephone,

        /** EMAIL PIC X(100). */
        @JsonProperty("email")     String email,

        /**
         * ADMINDATE PIC X(10) – expected in YYYY-MM-DD format from the JSON
         * source, converted to MM/DD/YYYY by paragraph 0210-MOVE-TABLE.
         */
        @JsonProperty("admindate") String adminDate,

        /** SALARY PIC 9(6)V9(2) COMP-3. */
        @JsonProperty("salary")    BigDecimal salary,

        /** DEPTID PIC 9(9). */
        @JsonProperty("deptid")    long deptId
) {}

