package com.example.suinsrt.dto;

import java.math.BigDecimal;

/**
 * Internal transfer object produced by paragraph 0210-MOVE-TABLE.
 *
 * <p>Corresponds to the LINKAGE SECTION structure LS-EMPLIST with its
 * length-prefixed string fields (LS-FIRSTNAME_L / LS-FIRSTNAME_T, etc.).
 * The length fields are preserved as Java int values to maintain full
 * fidelity with the COBOL logic.
 */
public record EmployeeProcessed(

        /** LS-EMPID PIC X(8) – EMPID after +10 000 000, stored as String. */
        String empIdStr,

        /** Raw numeric empId for service use. */
        long empId,

        /** Plain-text password (will be replaced by CRYPTPGM result). */
        String password,

        // ── firstName ───────────────────────────────────────────────
        /** LS-FIRSTNAME_L – length of non-space content. */
        int firstNameLength,
        /** LS-FIRSTNAME_T. */
        String firstName,

        // ── lastName ────────────────────────────────────────────────
        int lastNameLength,
        String lastName,

        // ── address ─────────────────────────────────────────────────
        /** Note: COBOL adds +5 to address length (preserved faithfully). */
        int addressLength,
        String address,

        // ── city ────────────────────────────────────────────────────
        int cityLength,
        String city,

        // ── zipCode ─────────────────────────────────────────────────
        int zipCodeLength,
        String zipCode,

        // ── telephone ───────────────────────────────────────────────
        /**
         * LS-TELEPHONE_L – COBOL tallies spaces from FIRSTNAME (not TELEPHONE)
         * when computing the telephone length; this quirk is preserved.
         */
        int telephoneLength,
        String telephone,

        // ── email ───────────────────────────────────────────────────
        int emailLength,
        String email,

        // ── dates / salary / dept ───────────────────────────────────
        /** LS-ADMIDATE – MM/DD/YYYY after rearrangement. */
        String adminDate,
        BigDecimal salary,
        long deptId
) {}

