package com.example.suinsrt.service;

import com.example.suinsrt.dto.CryptRequest;
import com.example.suinsrt.dto.CryptResponse;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestTemplate;

/**
 * Replaces {@code CALL 'CRYPTPGM' USING PASSW, EMPID, ADMINDATE}.
 *
 * <p>The COBOL paragraph 0300-CRYPT-PASS delegated password encryption to
 * the external sub-program CRYPTPGM. This service calls an equivalent
 * REST micro-service. If the micro-service is unavailable the plain-text
 * password is returned unchanged (graceful degradation) and a warning is
 * logged so that the caller can decide how to handle it.
 */
@Service
public class PasswordCryptoService {

    private static final Logger LOG = LoggerFactory.getLogger(PasswordCryptoService.class);

    private final RestTemplate restTemplate;
    private final String cryptoBaseUrl;

    public PasswordCryptoService(
            RestTemplate restTemplate,
            @Value("${app.crypto.base-url}") String cryptoBaseUrl) {
        this.restTemplate  = restTemplate;
        this.cryptoBaseUrl = cryptoBaseUrl;
    }

    /**
     * Encrypts {@code password} by calling the CRYPTPGM REST endpoint.
     *
     * @param password  plain-text password (PASSW)
     * @param empId     employee ID string (EMPID)
     * @param adminDate administration date (ADMINDATE)
     * @return encrypted password, or the original password if the service call fails
     */
    public String encrypt(String password, String empId, String adminDate) {
        try {
            CryptRequest  request  = new CryptRequest(password, empId, adminDate);
            CryptResponse response = restTemplate.postForObject(
                    cryptoBaseUrl + "/api/encrypt", request, CryptResponse.class);
            if (response != null && response.encryptedPassword() != null) {
                return response.encryptedPassword();
            }
        } catch (Exception ex) {
            LOG.warn("CRYPTPGM service unavailable – password will not be encrypted. EmpId={} error={}",
                     empId, ex.getMessage());
        }
        return password;
    }
}

// === FILE: src/main/java/com/example/suinsrt/service/EmployeeTransformService.java ===
package com.example.suinsrt.service;

import com.example.suinsrt.dto.EmployeeInputRecord;
import com.example.suinsrt.dto.EmployeeProcessed;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.util.ArrayList;
import java.util.List;

/**
 * Implements the data-transformation logic of COBOL paragraphs
 * 0210-MOVE-TABLE and 0300-CRYPT-PASS.
 *
 * <h2>Paragraph mapping</h2>
 * <ul>
 *   <li>{@link #transformAll(List)} → outer PERFORM VARYING COUNT1 loop</li>
 *   <li>{@link #transformRecord(EmployeeInputRecord)} → 0210-MOVE-TABLE body</li>
 * </ul>
 */
@Service
public class EmployeeTransformService {

    private static final Logger LOG = LoggerFactory.getLogger(EmployeeTransformService.class);

    /** Maximum table size – OCCURS 30 TIMES in COBOL. */
    public static final int MAX_EMPLOYEES = 30;

    /**
     * Transforms up to {@value #MAX_EMPLOYEES} raw input records into
     * their processed counterparts, faithfully reproducing paragraph
     * 0210-MOVE-TABLE for each entry where EMPID IS NUMERIC (i.e. > 0).
     *
     * @param inputs raw records from JSON parsing
     * @return list of processed records (may be shorter than input if records are skipped)
     */
    public List<EmployeeProcessed> transformAll(List<EmployeeInputRecord> inputs) {
        List<EmployeeProcessed> results = new ArrayList<>();

        // PERFORM 0210-MOVE-TABLE VARYING COUNT1 FROM 1 BY 1 UNTIL COUNT1 > 30
        int limit = Math.min(inputs.size(), MAX_EMPLOYEES);
        for (int i = 0; i < limit; i++) {
            EmployeeInputRecord raw = inputs.get(i);
            if (isNumericAndValid(raw.empId())) {
                results.add(transformRecord(raw));
            } else {
                LOG.info("Skipping record index={} – EMPID is not numeric/valid: {}", i, raw.empId());
            }
        }
        return results;
    }

    /**
     * Transforms a single raw employee record – the body of paragraph 0210-MOVE-TABLE.
     *
     * <h3>Key transformations applied</h3>
     * <ol>
     *   <li>ADD 10 000 000 TO EMPID</li>
     *   <li>Compute length of each string field (total width − number of trailing spaces)</li>
     *   <li>Address length gets an extra +5 (COBOL quirk preserved)</li>
     *   <li>Telephone length is calculated from FIRSTNAME spaces, not TELEPHONE (COBOL quirk preserved)</li>
     *   <li>Date rearrangement: YYYY-MM-DD → MM/DD/YYYY</li>
     * </ol>
     *
     * @param raw one entry from the parsed JSON array
     * @return transformed record ready for persistence
     */
    public EmployeeProcessed transformRecord(EmployeeInputRecord raw) {

        // ADD 10000000 TO EMPID(COUNT1)
        long adjustedEmpId = raw.empId() + 10_000_000L;

        // MOVE EMPID(COUNT1) TO LS-EMPID(COUNT1)  →  String, 8 chars
        String empIdStr = String.format("%8d", adjustedEmpId);

        // ── FIRSTNAME ─────────────────────────────────────────────────────
        String firstName = padOrTruncate(raw.firstName(), 30);
        int firstNameSpaces = countTrailingAndEmbeddedSpaces(firstName, 30);
        // COMPUTE COUNT3 = 30 - COUNT2
        int firstNameLength = 30 - firstNameSpaces;

        // ── LASTNAME ──────────────────────────────────────────────────────
        String lastName = padOrTruncate(raw.lastName(), 30);
        int lastNameSpaces = countTrailingAndEmbeddedSpaces(lastName, 30);
        int lastNameLength = 30 - lastNameSpaces;

        // ── ADDRESS ───────────────────────────────────────────────────────
        String address = padOrTruncate(raw.address(), 100);
        int addressSpaces = countTrailingAndEmbeddedSpaces(address, 100);
        // COMPUTE COUNT3 = 100 - COUNT2 + 5  (the +5 is a COBOL quirk)
        int addressLength = 100 - addressSpaces + 5;

        // ── CITY ──────────────────────────────────────────────────────────
        String city = padOrTruncate(raw.city(), 50);
        int citySpaces = countTrailingAndEmbeddedSpaces(city, 50);
        int cityLength = 50 - citySpaces;

        // ── ZIPCODE ───────────────────────────────────────────────────────
        String zipCode = padOrTruncate(raw.zipCode(), 15);
        int zipCodeSpaces = countTrailingAndEmbeddedSpaces(zipCode, 15);
        int zipCodeLength = 15 - zipCodeSpaces;

        // ── TELEPHONE ─────────────────────────────────────────────────────
        String telephone = padOrTruncate(raw.telephone(), 10);
        // COBOL bug preserved: tallying spaces from FIRSTNAME, not TELEPHONE
        int telephoneSpaces = countTrailingAndEmbeddedSpaces(firstName, 30);
        // COMPUTE COUNT3 = 10 - COUNT2  (COUNT2 comes from FIRSTNAME tally)
        int telephoneLength = 10 - telephoneSpaces;

        // ── EMAIL ─────────────────────────────────────────────────────────
        String email = padOrTruncate(raw.email(), 100);
        int emailSpaces = countTrailingAndEmbeddedSpaces(email, 100);
        int emailLength = 100 - emailSpaces;

        // ── DATE REARRANGEMENT ────────────────────────────────────────────
        // COBOL source date format from JSON: YYYY-MM-DD (positions 1-10)
        // COBOL substrings (1-based):
        //   ADMINDATE(6:3)  → chars 6,7,8  → "-DD" or "MM-" depending on separator
        //   ADMINDATE(9:2)  → chars 9,10   → day digits
        //   ADMINDATE(1:4)  → chars 1-4    → year
        //
        // Resulting WS-DATE layout:
        //   positions 1-3 : ADMINDATE(6:3)   – e.g. "MM-"
        //   positions 4-5 : ADMINDATE(9:2)   – e.g. "DD"
        //   position  6   : '/'
        //   positions 7-10: ADMINDATE(1:4)   – e.g. "YYYY"
        //
        // For input "2022-09-15" this yields "09-15/2022" then stored back.
        // The logic is reproduced byte-for-byte.
        String adminDate = rearrangeDate(raw.adminDate());

        return new EmployeeProcessed(
                empIdStr,
                adjustedEmpId,
                raw.password(),
                firstNameLength, firstName,
                lastNameLength,  lastName,
                addressLength,   address,
                cityLength,      city,
                zipCodeLength,   zipCode,
                telephoneLength, telephone,
                emailLength,     email,
                adminDate,
                raw.salary(),
                raw.deptId()
        );
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    /**
     * Reproduces {@code INSPECT field TALLYING COUNT2 FOR ALL SPACES}.
     *
     * <p>COBOL INSPECT TALLYING FOR ALL SPACES counts every space character
     * anywhere in the field (not just trailing). This is faithfully reproduced.
     *
     * @param value  the field value (already padded to {@code fieldWidth})
     * @param fieldWidth declared PIC width
     * @return number of space characters in the field
     */
    private int countTrailingAndEmbeddedSpaces(String value, int fieldWidth) {
        if (value == null) return fieldWidth;
        String padded = padOrTruncate(value, fieldWidth);
        int count = 0;
        for (char c : padded.toCharArray()) {
            if (c == ' ') count++;
        }
        return count;
    }

    /**
     * Pads or truncates a string to exactly {@code width} characters,
     * mirroring COBOL PIC X(n) MOVE semantics.
     *
     * @param value source string (may be null)
     * @param width declared PIC width
     * @return exactly {@code width}-character string
     */
    private String padOrTruncate(String value, int width) {
        if (value == null) value = "";
        if (value.length() >= width) return value.substring(0, width);
        return String.format("%-" + width + "s", value);
    }

    /**
     * Reproduces the COBOL date-rearrangement sub-sequence in 0210-MOVE-TABLE.
     *
     * <pre>
     * MOVE ADMINDATE(COUNT1)(6:3)  TO WS-DATE(1:3)   → chars at index 5,6,7
     * MOVE ADMINDATE(COUNT1)(9:2)  TO WS-DATE(4:2)   → chars at index 8,9
     * MOVE '/'                     TO WS-DATE(6:1)   → literal '/'
     * MOVE ADMINDATE(COUNT1)(1:4)  TO WS-DATE(7:4)   → chars at index 0,1,2,3
     * MOVE WS-DATE TO ADMINDATE(COUNT1)
     * </pre>
     *
     * <p>COBOL uses 1-based substring notation: (offset:length).
     * Java uses 0-based: offset-1.
     *
     * <p>Example: "2022-09-15" → WS-DATE = "09-" + "15" + "/" + "2022" = "09-15/2022"
     *
     * @param adminDate raw date string from JSON (expected YYYY-MM-DD, length 10)
     * @return rearranged date string
     */
    String rearrangeDate(String adminDate) {
        if (adminDate == null || adminDate.length() < 10) {
            LOG.warn("adminDate '{}' is shorter than 10 chars – padding with spaces", adminDate);
            adminDate = padOrTruncate(adminDate, 10);
        }

        // COBOL 1-based positions → Java 0-based indices
        // WS-DATE(1:3)  ← ADMINDATE(6:3)  → Java: adminDate.substring(5, 8)
        String part1 = adminDate.substring(5, 8);   // 3 chars
        // WS-DATE(4:2)  ← ADMINDATE(9:2)  → Java: adminDate.substring(8, 10)
        String part2 = adminDate.substring(8, 10);  // 2 chars
        // WS-DATE(6:1)  = '/'
        // WS-DATE(7:4)  ← ADMINDATE(1:4)  → Java: adminDate.substring(0, 4)
        String part3 = adminDate.substring(0, 4);   // 4 chars

        // Assemble WS-DATE = part1 + part2 + '/' + part3
        // Total = 3 + 2 + 1 + 4 = 10 characters
        return part1 + part2 + "/" + part3;
    }

    /**
     * Guards against non-positive EMPID values.
     * COBOL {@code IF EMPID IS NUMERIC} passes when the PIC 9 field
     * contains only digit characters (i.e. a valid unsigned integer > 0).
     */
    private boolean isNumericAndValid(long empId) {
        return empId > 0;
    }
}

