package com.example.suinsrt.service;

import com.example.suinsrt.dto.BulkInsertResponse;
import com.example.suinsrt.dto.EmployeeInputRecord;
import com.example.suinsrt.dto.EmployeeProcessed;
import com.example.suinsrt.model.Employee;
import com.example.suinsrt.repository.EmployeeRepository;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;

/**
 * Orchestrates the full SUINSRT flow:
 * <ol>
 *   <li>0100-OPEN-FILE  → parse JSON from InputStream</li>
 *   <li>0200-READ-PROCESS → deserialise up to 30 records</li>
 *   <li>0210-MOVE-TABLE  → delegate to {@link EmployeeTransformService}</li>
 *   <li>0300-CRYPT-PASS  → delegate to {@link PasswordCryptoService}</li>
 *   <li>0400-END-FILE    → stream is closed by caller; persist records</li>
 * </ol>
 */
@Service
public class EmployeeInsertService {

    private static final Logger LOG = LoggerFactory.getLogger(EmployeeInsertService.class);

    private final EmployeeRepository       employeeRepository;
    private final EmployeeTransformService transformService;
    private final PasswordCryptoService    cryptoService;
    private final ObjectMapper             objectMapper;

    public EmployeeInsertService(
            EmployeeRepository       employeeRepository,
            EmployeeTransformService transformService,
            PasswordCryptoService    cryptoService,
            ObjectMapper             objectMapper) {
        this.employeeRepository = employeeRepository;
        this.transformService   = transformService;
        this.cryptoService      = cryptoService;
        this.objectMapper       = objectMapper;
    }

    /**
     * Main entry point – replaces the MAIN-PARA in COBOL.
     *
     * <p>Reads a JSON {@link InputStream} containing an array of up to
     * {@value EmployeeTransformService#MAX_EMPLOYEES} employee objects,
     * transforms them, encrypts passwords, and persists to PostgreSQL.
     *
     * @param jsonStream UTF-8 JSON input stream (the EMPLIST file)
     * @return summary of what was inserted and what was skipped
     * @throws Exception if the JSON cannot be parsed
     */
    @Transactional
    public BulkInsertResponse processEmployeeJson(InputStream jsonStream) throws Exception {

        // ── 0100-OPEN-FILE / 0200-READ-PROCESS ──────────────────────
        // JSON PARSE IN-JSON INTO WS-EMPLIST
        List<EmployeeInputRecord> rawRecords = parseJson(jsonStream);
        LOG.info("JSON parsed – {} raw records found (max {})",
                 rawRecords.size(), EmployeeTransformService.MAX_EMPLOYEES);

        int totalReceived = Math.min(rawRecords.size(), EmployeeTransformService.MAX_EMPLOYEES);

        // ── 0210-MOVE-TABLE ─────────────────────────────────────────
        List<EmployeeProcessed> processed = transformService.transformAll(rawRecords);
        LOG.info("{} records passed EMPID numeric check", processed.size());

        // ── 0300-CRYPT-PASS (PERFORM VARYING COUNT1 FROM 1 BY 1) ────
        List<Employee>  toSave        = new ArrayList<>();
        List<String>    skippedReasons = new ArrayList<>();
        int             skipped       = totalReceived - processed.size();

        for (EmployeeProcessed p : processed) {

            // CALL 'CRYPTPGM' USING PASSW(COUNT1), EMPID(COUNT1), ADMINDATE(COUNT1)
            String encryptedPassword = cryptoService.encrypt(
                    p.password(),
                    p.empIdStr().trim(),
                    p.adminDate());

            Employee entity = new Employee(
                    p.empId(),
                    encryptedPassword,
                    p.firstName().stripTrailing(),
                    p.lastName().stripTrailing(),
                    p.address().stripTrailing(),
                    p.city().stripTrailing(),
                    p.zipCode().stripTrailing(),
                    p.telephone().stripTrailing(),
                    p.email().stripTrailing(),
                    p.adminDate(),
                    p.salary(),
                    p.deptId()
            );
            toSave.add(entity);
        }

        // ── Persist (replaces DB2 INSERT in the called main program) ─
        employeeRepository.saveAll(toSave);
        LOG.info("{} employees persisted to database", toSave.size());

        // ── 0400-END-FILE ────────────────────────────────────────────
        // Stream is closed by the controller/caller.

        return new BulkInsertResponse(
                totalReceived,
                toSave.size(),
                skipped,
                skippedReasons
        );
    }

    // ----------------------------------------------------------------
    // Private helpers
    // ----------------------------------------------------------------

    /**
     * Parses the raw JSON stream.
     *
     * <p>The COBOL program accepts a flat record of 13 000 bytes that the
     * {@code JSON PARSE} verb processes. Jackson replaces this with standard
     * JSON array deserialisation. Both a JSON array ({@code [...]}) and a
     * JSON object with an "employees" wrapper are accepted for robustness.
     */
    @SuppressWarnings("unchecked")
    private List<EmployeeInputRecord> parseJson(InputStream stream) throws Exception {
        // Try array first; fall back to wrapped object
        byte[] bytes = stream.readAllBytes();
        String json  = new String(bytes, java.nio.charset.StandardCharsets.UTF_8).trim();

        if (json.startsWith("[")) {
            return objectMapper.readValue(json,
                    new TypeReference<List<EmployeeInputRecord>>() {});
        }
        // Wrapped: { "employees": [...] }
        var root = objectMapper.readTree(json);
        var node = root.has("employees") ? root.get("employees") : root;
        return objectMapper.convertValue(node,
                new TypeReference<List<EmployeeInputRecord>>() {});
    }
}

