package com.example.suinsrt.controller;

import com.example.suinsrt.dto.BulkInsertResponse;
import com.example.suinsrt.service.EmployeeInsertService;
import jakarta.validation.constraints.NotNull;
import org.springframework.http.HttpStatus;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;

import java.io.InputStream;

/**
 * REST controller that exposes the SUINSRT functionality.
 *
 * <p>Two endpoints are provided:
 * <ul>
 *   <li>{@code POST /api/employees/upload} – accepts a multipart JSON file
 *       (direct replacement of reading the EMPLIST sequential file).</li>
 *   <li>{@code POST /api/employees/json}   – accepts a raw JSON request body
 *       (convenient for programmatic callers).</li>
 * </ul>
 */
@RestController
@RequestMapping("/api/employees")
@Validated
public class EmployeeInsertController {

    private final EmployeeInsertService insertService;

    public EmployeeInsertController(EmployeeInsertService insertService) {
        this.insertService = insertService;
    }

    /**
     * Accepts a multipart file upload containing a JSON employee list.
     *
     * <p>Mirrors the COBOL flow of opening and reading the EMPLIST sequential
     * file, then passing control to the JSON-parse and transform paragraphs.
     *
     * @param file multipart JSON file (max 1 MB, configured in application.properties)
     * @return {@link BulkInsertResponse} with insert statistics
     */
    @PostMapping(
            value  = "/upload",
            consumes = MediaType.MULTIPART_FORM_DATA_VALUE,
            produces = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<BulkInsertResponse> uploadJsonFile(
            @RequestPart("file") @NotNull MultipartFile file) {

        if (file.isEmpty()) {
            return ResponseEntity.badRequest().build();
        }

        try (InputStream is = file.getInputStream()) {
            BulkInsertResponse response = insertService.processEmployeeJson(is);
            return ResponseEntity.status(HttpStatus.CREATED).body(response);
        } catch (Exception ex) {
            throw new RuntimeException("Failed to process employee JSON file", ex);
        }
    }

    /**
     * Accepts a raw JSON body containing the employee array.
     *
     * @param jsonBody raw JSON string
     * @return {@link BulkInsertResponse} with insert statistics
     */
    @PostMapping(
            value    = "/json",
            consumes  = MediaType.APPLICATION_JSON_VALUE,
            produces  = MediaType.APPLICATION_JSON_VALUE
    )
    public ResponseEntity<BulkInsertResponse> insertFromJsonBody(
            @RequestBody String jsonBody) {

        try (InputStream is = new java.io.ByteArrayInputStream(
                jsonBody.getBytes(java.nio.charset.StandardCharsets.UTF_8))) {
            BulkInsertResponse response = insertService.processEmployeeJson(is);
            return ResponseEntity.status(HttpStatus.CREATED).body(response);
        } catch (Exception ex) {
            throw new RuntimeException("Failed to process employee JSON body", ex);
        }
    }
}

